insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('write-fairy-tale-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Write Fairy Tale', 'An activity that develops written expression.', 25, '20–30 min', 'Pencil and paper', 'Traditional fairy tale with a twist: the villain wins, the hero fails, the ending is ambiguous. Genre subversion.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('punctuation-colon-semicolon-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Punctuation Colon Semicolon', 'A skill-building activity focused on language, literacy and expression.', 8, '5–10 min', 'Printed text + pencil and paper', 'Colon introduces a list or explanation; semicolon joins two related clauses. Identify in texts; use in own writing.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('compound-complex-sentences-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Compound-Complex Sentences', 'An activity that develops written expression.', 8, '5–10 min', 'Pencil and paper', 'Although she was tired, she finished her work, and then she slept.'' Subordinate + coordinate clauses combined.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-song-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Write Song', 'A practical challenge that builds written expression.', 18, '15–20 min', 'Pencil and paper', 'Verse-chorus structure, 4 lines per section, end rhyme or near-rhyme. Setting own words to a simple self-composed melody.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('critical-reading-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Critical Reading', 'A practical challenge that builds reading development.', 13, '10–15 min', 'Any persuasive text', 'Why did the author write this? Who is the intended audience? What do they want you to believe?'' Critical literacy.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('start-reading-journal-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Start Reading Journal', 'A practical challenge that builds reading development.', 8, '5–10 min', 'Journal + pencil', 'After each chapter: one event you remember, one thing you''re wondering, one connection to your life.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('descriptive-writing-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Descriptive Writing', 'A skill-building activity focused on vocabulary depth.', 13, '10–15 min', 'Pencil and paper + a chosen place', 'Describe a place using only sensory details: no adjectives like ''nice'' or ''good.'' Specific sensory language.', 'This supports the vocabulary and expression that school will increasingly demand. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('percentages-amounts-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Percentages Amounts', 'A skill-building activity focused on reasoning, planning and problem-solving.', 8, '5–10 min', 'Pencil and paper', '20% of 50 = 10. Find 10%, then double. Percentages in real contexts: sale price, tip, score.', 'Understanding at this stage grows from working things out rather than being told the answer. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('roman-numerals-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Roman Numerals', 'A practical challenge that builds applied literacy thinking.', 7, '5–8 min', 'None', 'I, V, X, L, C, D, M. Read and write years in Roman numerals. Historical + mathematical literacy.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('surface-area-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Surface Area', 'A skill-building activity focused on spatial reasoning and planning.', 8, '5–10 min', 'Paper, scissors, ruler', 'Unfold a cube: how many faces? Each face''s area × 6. Net of a 3D shape is spatial reasoning.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('economics-supply-demand-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Economics Supply Demand', 'A practical challenge that builds reasoning, planning and problem-solving.', 13, '10–15 min', 'None (or market visit)', 'If there''s lots of something, the price goes down. If there''s little, it goes up. Real-world example: market visit.', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('scientific-method-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Scientific Method', 'An activity that develops scientific reasoning.', 25, '20–30 min', 'Experiment materials (chosen by child)', 'Question → Research → Hypothesis → Experiment → Analyse → Conclude → Report. Run a full cycle on one question.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('human-rights-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Human Rights', 'A practical challenge that builds reasoning, planning and problem-solving.', 8, '5–10 min', 'None', 'Name 5 universal human rights and give a real example of each. Rights as a concept before civics education.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('self-assess-academic-work-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Self-Assess Academic Work', 'A practical challenge that builds social understanding and self-regulation.', 13, '10–15 min', 'Own piece of work', 'Grade your own work before seeing an adult''s assessment. Where did your assessment and theirs differ? Why?', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('manage-long-term-projects-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Manage Long-Term Projects', 'A skill-building activity focused on social understanding and self-regulation.', null, 'Ongoing', 'None', 'A project with a 2-week deadline: plan backwards from deadline to identify daily/weekly tasks.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('cross-cultural-friendship-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Cross-Cultural Friendship', 'A practical challenge that builds friendship and social navigation.', null, 'Ongoing', 'None', 'Actively build a friendship with someone from a different background, city, or school. Intentional social expansion.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('compassion-vs-pity-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Compassion vs Pity', 'A skill-building activity focused on emotional regulation and self-awareness.', 8, '5–10 min', 'None', 'What''s the difference between feeling sorry for someone and actually helping them?'' Compassion as active.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('handle-public-mistake-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Handle Public Mistake', 'A skill-building activity focused on emotional regulation and self-awareness.', null, 'Ongoing', 'None', 'When you get something wrong in front of others: stay calm, acknowledge, correct, continue. Public error management.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-privilege-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Understand Privilege', 'An activity that develops social understanding and self-regulation.', 8, '5–10 min', 'None', 'What do we have that others don''t, through no effort of our own?'' Age-appropriate awareness of luck and circumstance.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('build-solar-oven-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Build Solar Oven', 'A skill-building activity focused on sensory discrimination and integration.', 25, '20–30 min', 'Cardboard box, foil, clingfilm, food to cook', 'Box, foil, clingfilm. Heat builds up and cooks food slowly. Solar energy + thermodynamics.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('grow-crystals-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Grow Crystals', 'A skill-building activity focused on sensory exploration through water.', null, 'Ongoing', 'Salt or sugar, water, jar, string', 'Dissolve salt or sugar in hot water; let cool slowly on a string. Crystal formation as ordered molecular structure.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-pinhole-camera-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Make Pinhole Camera', 'An activity that develops sensory discrimination and integration.', 18, '15–20 min', 'Dark box, foil, pin, tracing paper', 'Pinhole in a dark box projects an inverted image. Optics: light travels in straight lines.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('soap-making-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Soap Making', 'An activity that develops sensory exploration through water.', 25, '20–30 min', 'Glycerine soap base, essential oil, colour, mould', 'Glycerine melt-and-pour soap with added scent and colour. Chemistry: saponification principle accessible version.', 'This supports regulation and focus, which matters more once formal learning begins. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('textile-printing-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Textile Printing', 'A skill-building activity focused on sensory art and material handling.', 18, '15–20 min', 'Fabric, frame, stencil, fabric paint', 'Stretch fabric over a frame; apply paint through a stencil. Screen printing is industrial design made accessible.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('budget-week-s-meals-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Budget Week''s Meals', 'A skill-building activity focused on simple food preparation.', 18, '15–20 min', 'Pencil, paper, budget amount', 'Plan a week of meals for the family within a set budget. Arithmetic + nutrition knowledge + planning combined.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('cook-from-recipe-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Cook from Recipe', 'A practical challenge that builds simple food preparation.', 38, '30–45 min', 'Recipe book + kitchen access', 'Choose a recipe, gather ingredients, cook from start to finish without help. Culinary literacy + independence.', 'This develops the organisation and self-management that school increasingly demands. Expect them to want to do it their own way, and let them where you can.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('field-sport-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Field Sport', 'An activity that develops climbing and whole-body strength.', 60, '60–60 min', 'Sport-specific equipment + players', 'Play a full 60-minute session of a team sport with proper rules, positions, and substitutions.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swim-flip-turn-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Swim Flip Turn', 'An activity that develops swimming technique.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, practise a tumble turn at the pool wall: flip, push, glide, resume stroke. Technical swimming milestone.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('cycling-descent-control-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Cycling Descent Control', 'An activity that develops cycling skill and road awareness.', 18, '15–20 min', 'Bicycle + hill', 'Control speed on a long downhill: brake timing, body position, steering. Downhill safety = motor + judgement.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('walkover-or-backbend-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Walkover or Backbend', 'A practical challenge that builds coordination, strength and control.', 13, '10–15 min', 'Soft mat', 'Back walkover or front walkover. Full spinal flexibility + weight-bearing in back-extended position.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('athletics-800m-run-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Athletics 800m Run', 'A practical challenge that builds running speed and endurance.', 8, '5–10 min', 'Track or open space', 'Run 800 m with pacing strategy: don''t sprint the first lap. Pacing is a cognitive and physical skill simultaneously.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('basketball-dribble-shoot-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Basketball Dribble Shoot', 'A skill-building activity focused on ball control with the feet.', 13, '10–15 min', 'Basketball + basket (or improvised)', 'Dribble around a defender and shoot. Game-like combination rather than isolated skill practice.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('surfing-or-bodyboard-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Surfing or Bodyboard', 'A skill-building activity focused on advanced balance and control.', 38, '30–45 min', 'Board + sea access', 'Balance on a moving water surface. The most demanding vestibular and proprioceptive challenge available.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('martial-arts-sparring-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Martial Arts Sparring', 'A skill-building activity focused on coordination, strength and control.', 18, '15–20 min', 'Partner + instructor', 'Supervised light sparring. Reading an opponent + responding in real time = the highest-level motor planning.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('complete-short-story-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Complete Short Story', 'A skill-building activity focused on handwriting control.', 38, '30–45 min', 'Pencil and paper', 'A complete, edited short story: 1500 words. Character, conflict, resolution: revised twice before considered done.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('wearable-tech-design-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Wearable Tech Design', 'An activity that develops fine motor precision and control.', 18, '15–20 min', 'Drawing materials', 'Design a device that could go on the body: what does it do, how is it powered, what problem does it solve?', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('book-binding-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Book Binding', 'An activity that develops needle skills and precision.', 25, '20–30 min', 'Paper, needle, wax thread, bone folder', 'Fold and stitch a 16-page booklet with a pamphlet stitch. The book''s structure becomes comprehensible.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('make-diorama-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Make Diorama', 'A practical challenge that builds fine motor precision and control.', 25, '20–30 min', 'Cardboard box, paint, paper, small objects', 'A 3D scene in a box: painted background, layered paper elements, miniature figures. Theatrical design thinking.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('rigid-heddle-loom-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Rigid Heddle Loom', 'An activity that develops needle skills and precision.', 38, '30–45 min', 'Rigid heddle loom (or cardboard loom)', 'Simple table loom: warp, weave, beat, advance. The structure of cloth becomes visible and learnable.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('calligraphy-full-alphabet-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Calligraphy Full Alphabet', 'A skill-building activity focused on handwriting control.', 25, '20–30 min', 'Calligraphy pen or marker, paper', 'Write the full lowercase alphabet in an italic calligraphic hand. Letterform + pressure + consistency.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('novel-3-chapters-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Novel 3 Chapters', 'An activity that develops written expression.', 38, '30–45 min', 'Pencil and paper', 'Write 3 chapters of an intended longer novel. Sustaining characters across chapters requires planning and consistency.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('socratic-seminar-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Socratic Seminar', 'A skill-building activity focused on conversation and presentation.', 25, '20–30 min', 'None', 'Guided discussion of a big question with 3+ people: ''Is it ever right to break a rule?'' Listen and build on others.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-speech-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Write Speech', 'An activity that develops written expression.', 18, '15–20 min', 'Pencil and paper', 'A 400-word speech on a real topic. Opening hook + 3 arguments + call to action. Rhetoric as a skill.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('literary-devices-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Literary Devices', 'A practical challenge that builds language, literacy and expression.', 13, '10–15 min', 'Pencil and paper', 'Metaphor, simile, personification, alliteration, onomatopoeia: identify and use all 5 in a single paragraph.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('letter-future-self-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Letter Future Self', 'A practical challenge that builds written expression.', 13, '10–15 min', 'Pencil, paper, envelope', 'Write a letter to open in 5 years: who you are now, what you hope for, what you worry about.', 'This supports the vocabulary and expression that school will increasingly demand. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('analyse-speech-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Analyse Speech', 'An activity that develops reading development.', 13, '10–15 min', 'Printed speech text', 'Read a famous speech. Identify: the audience, the purpose, 2 rhetorical devices, the call to action.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('collaborative-story-writing-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Collaborative Story Writing', 'A practical challenge that builds written expression.', 25, '20–30 min', 'Pencil and paper (shared)', 'Write alternating chapters with a parent or friend: one person writes chapter 1, the other writes chapter 2.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-research-essay-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Write Research Essay', 'An activity that develops written expression.', 25, '20–30 min', 'Reference materials + pencil and paper', '400 words with an argument, 3 pieces of evidence from different sources, and a conclusion. Academic writing beginning.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('ratio-proportion-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Ratio Proportion', 'A practical challenge that builds reasoning, planning and problem-solving.', 8, '5–10 min', 'Recipe + cooking context', 'If 3 cups make 1 batch, how many cups for 2 batches? Proportional reasoning in cooking + mathematics.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('angles-measuring-protractor-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Angles Measuring Protractor', 'An activity that develops spatial reasoning and planning.', 8, '5–10 min', 'Protractor, ruler, pencil, paper', 'Measure and draw angles to within 5 degrees. Protractor use = spatial measurement tool.', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('prime-numbers-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Prime Numbers', 'A practical challenge that builds number and early mathematical thinking.', 13, '10–15 min', 'Grid paper', 'Identify prime numbers to 50 using the Sieve of Eratosthenes. Pattern-based mathematical discovery.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('volcanoes-plate-tectonics-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Volcanoes Plate Tectonics', 'A skill-building activity focused on scientific reasoning.', 8, '5–10 min', 'None', 'Why do volcanoes happen? Plate tectonics model. Geography + geology + scale comprehension.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('photosynthesis-equation-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Photosynthesis Equation', 'A practical challenge that builds planning and problem-solving.', 7, '5–8 min', 'None', 'CO2 + water + light → glucose + oxygen. The equation of life: every plant, every breath.', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('historical-empathy-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Historical Empathy', 'An activity that develops reasoning, planning and problem-solving.', 13, '10–15 min', 'Historical reference or book', 'Put yourself in [historical person''s] position. What would you have done? What did they know that we don''t?''', 'At this age children can genuinely think through a problem, and doing so builds the habit of persisting with hard things. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('manage-peer-pressure-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Manage Peer Pressure', 'A skill-building activity focused on friendship and social navigation.', 13, '10–15 min', 'None', 'Role-play 3 peer pressure scenarios. Practise saying no in different ways: firm, funny, deflecting, leaving.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-anxiety-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Understand Anxiety', 'A skill-building activity focused on emotional regulation and self-awareness.', 8, '5–10 min', 'None', 'What does worry feel like in your body? Where does it live? What are you most worried about right now?''', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('loser-good-winner-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Loser Good Winner', 'A skill-building activity focused on managing competition and fairness.', 18, '15–20 min', 'Any competitive game', 'Both in the same session: play a game, win one, lose one, respond to each with class. Practice, not performance.', 'Social and emotional skills at this age predict how school goes as much as academic ability does. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('notice-systemic-unfairness-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Notice Systemic Unfairness', 'A practical challenge that builds managing competition and fairness.', 8, '5–10 min', 'None', 'Why might some people have more advantages than others from the start?'' Beginning structural thinking about society.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('own-mistakes-publicly-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Own Mistakes Publicly', 'A skill-building activity focused on resilience and persistence.', null, 'Ongoing', 'None', 'When you''ve done something wrong that others know about: acknowledge it without excessive excuse-making.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('reciprocity-relationships-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Reciprocity Relationships', 'A practical challenge that builds friendship and social navigation.', 7, '5–8 min', 'None', 'What have you given in your closest friendship this week? What have you received?'' Friendship as a two-way exchange.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('hydroponics-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Hydroponics', 'A skill-building activity focused on sensory exploration through water.', null, 'Ongoing', 'Container, water, plant food, seeds', 'Grow plants in water + nutrient solution without soil. Modern agriculture + biology + systematic care.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('electrolysis-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Electrolysis', 'A practical challenge that builds sensory exploration through water.', 13, '10–15 min', 'Salt, water, pencils, battery + wires', 'Salt water + two pencils + battery = bubbles of hydrogen and oxygen. Electricity splits water. Simple electrolysis.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-spectroscope-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Make Spectroscope', 'A practical challenge that builds sensory discrimination and integration.', 18, '15–20 min', 'CD, cardboard box, light', 'CD + cardboard box + light source. Split white light into the spectrum. Optics: dispersion of light.', 'Physical and sensory input remains important at this age, particularly for children who sit still for long periods at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('felting-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Felting', 'An activity that develops sensory exploration through water.', 25, '20–30 min', 'Wool roving, soap, hot water, bubble wrap', 'Wet felting: wool + hot water + soap, agitate until fibres lock. The science of fibre entanglement.', 'This supports regulation and focus, which matters more once formal learning begins. Expect them to want to do it their own way, and let them where you can.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('ethnobotany-walk-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Ethnobotany Walk', 'An activity that develops sensory discrimination and integration.', 25, '20–30 min', 'Field guide or elder knowledge', 'Walk through a local area: identify plants with traditional or practical uses. Local plant knowledge as science.', 'Sensory-rich activity gives children a break from cognitive demand while still developing skill. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('literacy-saving-interest-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Literacy Saving Interest', 'An activity that develops everyday independence and responsibility.', 8, '5–10 min', 'Pencil and paper', 'If you save 100 Rs and earn 5% interest per year, how much do you have after a year? Simple interest concept.', 'Children who genuinely contribute at home tend to be more capable and more confident. Expect them to want to do it their own way, and let them where you can.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('cook-international-meal-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Cook International Meal', 'An activity that develops simple food preparation.', 38, '30–45 min', 'Recipe + ingredients', 'Full meal from another country: recipe research, shopping, cooking, plating. Culinary geography.', 'Independence and responsibility at this age build competence that carries well beyond the specific task. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Activities of Daily Living; NCERT Foundational Stage; IAP'),
  ('design-sport-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Design Sport', 'A practical challenge that builds coordination, strength and control.', 25, '20–30 min', 'Paper for rules, improvised equipment', 'Invent a new sport: rules, equipment, team size, scoring. Systems thinking + creativity + fairness all embedded.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('swimming-racing-dive-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Swimming Racing Dive', 'A skill-building activity focused on swimming technique.', 13, '10–15 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, and only into water of a safe, confirmed depth, practise a racing dive from the blocks or pool edge. Explosive entry + streamline = technical swimming milestone.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('cycle-touring-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Cycle Touring', 'An activity that develops cycling skill and road awareness.', 105, '90–120 min', 'Bicycle, water, snack, route plan', 'Plan and execute a 10+ km cycling day trip with stops. Navigation, stamina, rest planning.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('advanced-gymnastics-sequence-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Advanced Gymnastics Sequence', 'A skill-building activity focused on ball control with the feet.', 18, '15–20 min', 'Soft floor surface', '7-element floor sequence with transitions. Choreographed gymnastics: the motor elements are now the canvas, not the goal.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('trail-running-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Trail Running', 'A skill-building activity focused on running speed and endurance.', 25, '20–30 min', 'Trail (park or natural path)', 'Run on uneven terrain for 3 km. Trail running recruits far more stabilising muscles than road running.', 'Skills at this age become more accurate and more strategic, and this is the kind of practice that develops both. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('yoga-flow-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Yoga Flow', 'A skill-building activity focused on coordination, strength and control.', 13, '10–15 min', 'None', '10-pose yoga sequence from memory, held 3 breaths each. Memory + breath + body alignment combined.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('tennis-serve-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Tennis Serve', 'An activity that develops swimming technique.', 13, '10–15 min', 'Racket, ball', 'Continental grip serve: toss, trophy position, contact, follow through. The serve is the most complex single stroke in tennis.', 'This refines coordination and control, and gives your child the physical competence that sport and play at school will draw on. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('ultimate-frisbee-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Ultimate Frisbee', 'A skill-building activity focused on coordination, strength and control.', 25, '20–30 min', 'Frisbee + players', 'Full game with disc rules, positions, and spirit of the game. Ultimate has a unique self-refereed model.', 'Physical activity now supports concentration, sleep and mood as much as it supports strength. Expect them to want to do it their own way, and let them where you can.', 'WHO Physical Activity Guidelines (5–17); AAP Sports and Fitness; IAP'),
  ('science-fiction-story-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Science Fiction Story', 'A practical challenge that builds fine motor precision and control.', 25, '20–30 min', 'Pencil and paper', 'Set in a plausible future world. Science underpins the fiction: what technology exists, why, and what problem it creates.', 'This refines the precision your child now needs for writing, drawing and detailed work at school. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('pottery-wheel-thrown-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Pottery Wheel-Thrown', 'A practical challenge that builds fine motor precision and control.', 38, '30–45 min', 'Potter''s wheel + clay (art school or studio)', 'Supervised session on a potter''s wheel. Centring clay on a moving wheel is the most demanding fine motor task in craft.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('knitting-first-garment-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Knitting First Garment', 'An activity that develops needle skills and precision.', 38, '30–45 min', 'Yarn, needles (large)', 'Knit a small rectangular scarf or wash cloth: 20 stitches, 40 rows. A complete, usable knitted object.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Expect them to want to do it their own way, and let them where you can.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('build-app-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Build App', 'A skill-building activity focused on construction and spatial precision.', 38, '30–45 min', 'Computer + no-code app platform (MIT App Inventor)', 'Build a functional app using a no-code platform. Real-world product: what problem does it solve?', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('map-making-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Map-Making', 'A practical challenge that builds drawing accuracy and detail.', 25, '20–30 min', 'Paper, pencil, ruler, coloured pens', 'Draw an imaginary world with 5 regions, a legend, a scale, compass rose, and geographic features.', 'Fine motor control at this age is about accuracy and endurance rather than basic ability. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'AOTA Fine Motor Development; NCERT Foundational Literacy; IAP'),
  ('make-documentary-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Make Documentary', 'A practical challenge that builds fine motor precision and control.', 25, '20–30 min', 'Phone for filming', 'Plan, film, and edit a 2-minute documentary about a local topic. Visual storytelling + interviewing + editing.', 'The hand skills built here support handwriting, and handwriting fluency frees up attention for thinking. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('write-mystery-story-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write Mystery Story', 'A skill-building activity focused on written expression.', 25, '20–30 min', 'Pencil and paper', 'A mystery requires: a mystery, red herrings, clues, a reveal, and a resolution. Plotting in reverse: start with the answer.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('debate-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Debate', 'A skill-building activity focused on explaining and reasoning aloud.', 18, '15–20 min', 'None', 'Statement + cross-examination. One side asks targeted questions to undermine the other''s argument. Advanced debate.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-personal-manifesto-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write Personal Manifesto', 'An activity that develops written expression.', 13, '10–15 min', 'Pencil and paper', 'These are the things I believe, the things I value, and the kind of person I am working to be.'' Identity in writing.', 'This supports the vocabulary and expression that school will increasingly demand. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('discuss-banned-book-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Discuss Banned Book', 'An activity that develops reading development.', 18, '15–20 min', 'Age-appropriate controversial/challenged book', 'Read (or excerpt of) a book that has been banned or challenged. Why? What does this tell us about society?', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Expect them to want to do it their own way, and let them where you can.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('epistolary-story-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Epistolary Story', 'A skill-building activity focused on narrative structure and retelling.', 18, '15–20 min', 'Pencil and paper', 'A story told entirely through letters, emails, or diary entries. A distinct narrative structure with its own rules.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('etymology-research-project-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Etymology Research Project', 'A practical challenge that builds vocabulary depth.', 25, '20–30 min', 'Etymological dictionary or resource', 'Choose 20 words from a single field (cooking, sport, medicine) and trace their origins. Language as historical record.', 'This supports the vocabulary and expression that school will increasingly demand. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-found-poem-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write Found Poem', 'A skill-building activity focused on reading development.', 13, '10–15 min', 'Newspaper or magazine article + pencil', 'Take a news article and isolate words to create a poem. Found poetry reveals the poetry already in language.', 'Language now becomes a tool for thinking, explaining and reading, and this strengthens all three. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('understand-narrative-unreliability-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Understand Narrative Unreliability', 'A skill-building activity focused on narrative structure and retelling.', 8, '5–10 min', 'Book or story extract', 'Is the narrator telling us everything? Are they being honest?'' Unreliable narrator as a literary device.', 'Being able to explain their thinking out loud helps children organise it, which is why talk matters at this age. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('square-roots-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Square Roots', 'An activity that develops number and early mathematical thinking.', 8, '5–10 min', 'Pencil and paper', 'What is the square root of 50? Between 7 (49) and 8 (64): closer to 7. Estimation + number sense combined.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('coordinate-geometry-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Coordinate Geometry', 'A practical challenge that builds number and early mathematical thinking.', 8, '5–10 min', 'Graph paper', 'Plot points in all 4 quadrants of a coordinate plane. Negative coordinates = number line extended into space.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('speed-distance-time-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Speed, Distance, Time', 'An activity that develops understanding time.', 8, '5–10 min', 'Pencil and paper', 'If I travel 60 km at 30 km/h, how long does it take? The formula and its rearrangements.', 'Understanding at this stage grows from working things out rather than being told the answer. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('genetics-introduction-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Genetics Introduction', 'A practical challenge that builds scientific reasoning.', 8, '5–10 min', 'None', 'Why do children look like parents? Genes carry information. Dominant and recessive traits with Mendel''s peas.', 'Understanding at this stage grows from working things out rather than being told the answer. Let your child attempt it independently first, and offer help only when they ask or genuinely stall.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('climate-science-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Climate Science', 'An activity that develops scientific reasoning.', 8, '5–10 min', 'None', 'Carbon dioxide + solar radiation + greenhouse effect. How does human activity change the climate? Evidence-based.', 'This develops the planning and reasoning that increasingly demanding schoolwork will require. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('philosophy-mind-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Philosophy Mind', 'A skill-building activity focused on reasoning, planning and problem-solving.', 13, '10–15 min', 'None', 'How do you know other people are conscious? How do you know YOU are conscious?'' Philosophy as lived inquiry.', 'Understanding at this stage grows from working things out rather than being told the answer. Expect them to want to do it their own way, and let them where you can.', 'NCERT Foundational Literacy and Numeracy; Harvard Center on the Developing Child; IAP'),
  ('emotional-regulation-toolkit-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Emotional Regulation Toolkit', 'A practical challenge that builds emotional regulation and self-awareness.', 13, '10–15 min', 'Paper for mapping', 'Map your own regulation tools: 5 things that calm you, 3 things that energise you, 2 things that ground you. Personal toolkit.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-cognitive-biases-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Understand Cognitive Biases', 'A practical challenge that builds social understanding and self-regulation.', 8, '5–10 min', 'None', 'Confirmation bias: we see what we already believe. Provide an example from own life. Self-awareness as critical thinking.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('practice-radical-honesty-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Practice Radical Honesty', 'An activity that develops empathy and perspective-taking.', 8, '5–10 min', 'None', 'One conversation where you say exactly what you think (with kindness). Honesty as a practice, not just a value.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('build-community-project-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Build Community Project', 'A skill-building activity focused on social understanding and self-regulation.', 18, '15–20 min', 'Paper for planning', 'Identify a small problem in your community and design a solution. Civic agency: from observation to action.', 'This supports the friendships, fairness and self-control that become central once children are in a classroom. Expect them to want to do it their own way, and let them where you can.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-news-cycle-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Understand News Cycle', 'An activity that develops empathy and perspective-taking.', 13, '10–15 min', 'Two news sources', 'Read the same story from two different publications. What''s different? Journalism, framing, and editorial perspective.', 'Your child can now reflect on their own behaviour, which makes real emotional learning possible. Talk about how they approached it rather than whether they got it right; the strategy is the valuable part.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP')
